mapper.select:
select a.*, woo.order_no, wwm.wave_no,wc.carrier_name
from wms_shipment a
left join wms_out_orders woo on a.order_id = woo.id
left join wms_wave_master wwm on a.wave_id = wwm.id
left join wms_carrier wc on a.carrier_id=wc.id
where 1=1


    and a.shipment_no = #{shipmentNo}



    and woo.order_no = #{orderNo}



    and woo.id = #{orderId}



    and wwm.wave_no = #{waveNo}



    and a.wave_id = #{waveId}
